import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])

    if n == 0 or m == 0:
        print("")
        return

    matrix = []
    idx = 2
    for i in range(n):
        row = list(map(int, data[idx:idx + m]))
        matrix.append(row)
        idx += m

    result = []

    # Extract anti-diagonals
    for d in range(n + m - 1):
        diag = []
        for i in range(n):
            j = d - i
            if 0 <= j < m:
                diag.append(matrix[i][j])
        if len(diag) > 1:
            result.extend([diag[0], diag[-1]])
        elif len(diag) == 1:
            result.append(diag[0])

    print(' '.join(map(str, result)))

if __name__ == "__main__":
    main()
